b:if.script:
//
/* tb-identity-presentation-b-20261107: native logo and exact stock credit presentation only. */
(function(){
 'use strict';
 var cfg={"slug":"saetimes","kind":"customer","source":"","native":false,"mirror":"[data-tb-logo-mirror=\"saetimes\"]","creditTargets":".st-dw-f p"};
 var queued=false;
 function tidy(s){return String(s||'').replace(/\s+/g,' ').trim();}
 function stockCredit(el){
  var text=tidy(el.textContent),links=el.querySelectorAll('a');
  var linked=/^Copyright © (\d{4})(?:\.)? Tema Blogger(?: \.)?\.?(?: )All rights reserved\.$/.exec(text);
  var year=linked&&linked[1];
  if(linked){
   if(links.length!==1||tidy(links[0].textContent)!=='Tema Blogger'||links[0].getAttribute('href')!=="https://www.temablogger.com/")return;
  }else{
   var legacy=cfg.slug==='saetimes'&&cfg.kind==='demo'&&/^© (\d{4}) SAETIMES\. All Right Reserved\.$/.exec(text);
   if(!legacy||links.length!==0)return;year=legacy[1];
  }
  var a=document.createElement('a');a.href="https://www.temablogger.com/";a.textContent='Tema Blogger';
  var y=el.querySelector('#year');if(y)y.textContent=year;
  el.replaceChildren(document.createTextNode('© '),y||document.createTextNode(year),document.createTextNode(' '),a,document.createTextNode('. All rights reserved.'));
 }
 function mirror(){
  if(!cfg.source)return;
  var src=document.querySelector(cfg.source);if(!src)return;
  var img=src.querySelector('img'),title=document.getElementById('tb-identity-blog-title');
  var name=cfg.native?tidy(title&&title.textContent):tidy(src.textContent);
  if(img)name=img.getAttribute('alt')||tidy(title&&title.textContent);
  if(!name)name=tidy(title&&title.textContent);
  document.querySelectorAll(cfg.mirror).forEach(function(target){
   if(target===src||src.contains(target))return;
   if(img&&img.getAttribute('src')){
    var old=target.querySelector('img');if(old&&old.getAttribute('src')===img.getAttribute('src'))return;
    var copy=img.cloneNode(true);copy.removeAttribute('id');copy.removeAttribute('width');copy.removeAttribute('height');
    target.replaceChildren(copy);
   }else if(name&&tidy(target.textContent)!==name)target.textContent=name;
  });
 }
 function apply(){queued=false;if(!document.body||document.body.id==='layout')return;
  if(cfg.creditTargets)document.querySelectorAll(cfg.creditTargets).forEach(stockCredit);
  mirror();
 }
 function schedule(){if(queued)return;queued=true;(window.requestAnimationFrame||function(f){setTimeout(f,0);})(apply);}
 function start(){apply();if(window.MutationObserver&&document.body)new MutationObserver(schedule).observe(document.body,{childList:true,subtree:true});}
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
})();
//
